export const options = {
    // 꼭 재사용하도록 고정 (연결 단계 지표 확인 목적)
    noConnectionReuse: false,

    // 한 눈에 보기 좋게 통계 지표 확장
    summaryTrendStats: ["avg", "med", "p(90)", "p(95)", "max", "count"],

    // 응답 본문이 불필요하면 I/O 줄이기 (선택)
    discardResponseBodies: true,

    scenarios: {
        toggle_like: {
            executor: "constant-vus",
            vus: VUS,            // ← 하드코딩 30 → 변수 사용
            duration: DURATION,  // ← "30s" → 변수 사용
            gracefulStop: "15s",
        },
    },
    thresholds: {
        http_req_failed: ["rate<0.01"],
        // 초기엔 조금 느슨하게 보고 튜닝 권장 (지금 p95가 1.3~1.6s 수준이었음)
        http_req_duration: ["p(95)<800"],

        // ★ 연결 단계 지표: 1분 이후 급등하면 NAT/백로그 이슈 신호
        http_req_connecting: ["p(95)<80"],

        // ★ 서버 대기(백엔드 처리/큐잉) 지표: 이게 튀면 앱/DB/컨슈머 측 병목
        http_req_waiting: ["p(95)<700"],
    },
};


export default function () {
    // __VU는 1부터 시작하므로 -1 해주면 더 균등해집니다
    const token = TOKENS[(__VU - 1) % TOKENS.length];
    const url = `${BASE_URL}/clubs/${CLUB_ID}/feeds/${FEED_ID}/likes`;

    const res = http.put(url, null, {
        headers: { Authorization: `Bearer ${token}` },
        tags: { endpoint: "feed_like_toggle", user: String(__VU) },
    });

    check(res, { "status is 200 or 204": (r) => r.status === 200 || r.status === 204 });

    // 동시성 충돌을 줄이기 위해 0.5~1.5초 랜덤 대기
    sleep(0.5 + Math.random());
}



